 d=root/'stage420';assert not(d/'readonly-plan.json').exists();p=read(d/'plan.json');files=[Path(__file__),Path(__file__).with_name('pilot420_json.py'),Path(__file__).with_name('test_pilot420_json.py'),Path(__file__).with_name('pilot420_run.py'),d/'executed-pilot420_run.py',d/'plan.json',d/'result.json',d/'stop-private.json',d/'repair-note.json',d/'qualification.json',d/'parent_C0-private.json',d/'parent_P-private.json',d/'decisions-private.json']+list(d.glob('P_decision1_*-private.json'))
