 decisions=read(d/'decisions-private.json');q=dict(stage=420,status='STOPPED_PILOT_PARTIAL_EVIDENCE_RECOVERED_READONLY',original_model_status=runresult['status'],original_error=runresult['error'],qualification_passed=qual['passed'],qualification_summary=summaries,C0=runresult['policies'][0],P_parent_decisions_committed=0,P_parent_rows=0,C0_decisions_committed=len(decisions),C0_selected_recipes=[z['selected_recipe'] for z in decisions],first_query_finished_model_branches=branches,read_only_first_query_rank=rank,model_closedloop_comparison_available=False,actual_opened=False,source_model_resumed=False,original_run_and_error_preserved=True,executed_runner_sha256=read(d/'repair-note.json')['executed_runner_sha256'],corrected_runner_sha256=read(d/'repair-note.json')['published_runner_sha256'],serialization_tests=tests.testsRun,test_failures=len(tests.failures),test_errors=len(tests.errors),new_native_or_model_calls=0,CPU_s=time.process_time()-cpu,wall_s=time.perf_counter()-wall);save(d/'readonly-result.json',q);print(json.dumps({k:v for k,v in q.items() if k not in ['qualification_summary','first_query_finished_model_branches']}))
